<section class="page-banner"><div class="container"><div class="section-label">PARTICIPATION INSIGHTS</div><h1><?= $reportClub?'Club participation report':'University participation report' ?></h1><p><?= $reportClub?e($reportClub['name']):'Events, registrations, attendance and feedback across campus clubs.' ?></p></div></section>
<section class="section container"><?php if(!$reportClub): ?><?php require dirname(__DIR__).'/partials/admin_nav.php'; ?><?php else: ?><p><a href="<?= e(url('leader',['club_id'=>$reportClub['id']])) ?>" class="back-link">← Back to club studio</a></p><?php endif; ?>
<div class="quick-stats"><div class="stat-card"><span>Events</span><strong><?= count($events) ?></strong></div><div class="stat-card"><span>Registered participants</span><strong><?= array_sum(array_column($events,'registered')) ?></strong></div><div class="stat-card"><span>Attended participants</span><strong><?= array_sum(array_column($events,'attended')) ?></strong></div></div>
<div class="section-heading slim"><h2>Club memberships</h2></div><div class="card panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Club</th><th>Approved members</th><th>Pending requests</th></tr></thead><tbody><?php foreach($memberships as $m): ?><tr><td><?= e($m['club_name']) ?></td><td><?= (int)$m['members'] ?></td><td><?= (int)$m['pending'] ?></td></tr><?php endforeach; ?><?php if(!$memberships): ?><tr><td colspan="3">No memberships available.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="section-heading slim"><h2>Event participation and feedback</h2></div><div class="card panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Event</th><th>Club</th><th>Date</th><th>Status</th><th>Registered</th><th>Present</th><th>Average rating</th></tr></thead><tbody><?php foreach($events as $ev): ?><tr><td><?= e($ev['title']) ?></td><td><?= e($ev['club_name']) ?></td><td><?= e(pretty_date($ev['starts_at'],'d M Y')) ?></td><td><?= status_pill($ev['status']) ?></td><td><?= (int)$ev['registered'] ?></td><td><?= (int)$ev['attended'] ?></td><td><?= $ev['avg_rating']!==null?e($ev['avg_rating']).' / 5':'—' ?></td></tr><?php endforeach; ?><?php if(!$events): ?><tr><td colspan="7">No events to report.</td></tr><?php endif; ?></tbody></table></div></div></section>
